import unittest

def calculate_discounted_price(price, discount):
    if discount < 0 or discount > 100:
        raise ValueError("Discount must be between 0 and 100 percent.")
    return price * (1 - discount / 100)

class TestCalculateDiscountedPrice(unittest.TestCase):
    def test_no_discount(self):
        self.assertEqual(calculate_discounted_price(100, 0), 100)

    def test_full_discount(self):
        self.assertEqual(calculate_discounted_price(100, 100), 0)

    def test_partial_discount(self):
        self.assertAlmostEqual(calculate_discounted_price(100, 50), 50)

    def test_fractional_price(self):
        self.assertAlmostEqual(calculate_discounted_price(99.99, 10), 89.991)

    def test_zero_price(self):
        self.assertEqual(calculate_discounted_price(0, 50), 0)

    def test_negative_discount(self):
        with self.assertRaises(ValueError):
            calculate_discounted_price(100, -10)

    def test_discount_over_100(self):
        with self.assertRaises(ValueError):
            calculate_discounted_price(100, 110)

if __name__ == '__main__':
    unittest.main()
```

